<script setup lang="ts">
import { ref, computed } from 'vue'
import WorkspaceShell from './shell/WorkspaceShell.vue'
import { analyse, saveEvidence, getEvidence, clearEvidence, type StudentId, type EvidenceRecord } from './adapters/learning'
import { CASES, DEFAULT_CASE_ID, getCase } from './adapters/cases'
import { submitReview, getReviews, reviewStats, type ReviewDecision } from './adapters/review'
const params=new URLSearchParams(location.search)
const role=ref<'student'|'teacher'>(params.get('role')==='teacher'?'teacher':'student')
const student=ref<StudentId>('A')
const answer=ref('')
const records=ref<EvidenceRecord[]>(getEvidence())
const latest=ref<EvidenceRecord|null>(null)
const error=ref('')
const caseId=ref<string>(params.get('case')??DEFAULT_CASE_ID)
const activeCase=computed(()=>getCase(caseId.value))
const reviews=ref(getReviews())
const stats=computed(()=>reviewStats(records.value,reviews.value))
if(params.get('demo')==='1'&&records.value.length===0){const demo=analyse('A','这是过拟合，训练 99% 与验证 78% 差距 21pt。我会加入正则化，并用独立验证集比较干预前后表现。');saveEvidence(demo);records.value=getEvidence();latest.value=demo}
const selected=computed(()=>records.value.filter(x=>x.student===student.value))
function chooseCase(id:string){caseId.value=id;latest.value=null;answer.value='';error.value=''}
function reviewOf(id:string){return reviews.value.find(r=>r.task_id===id)}
function reviewLabel(id:string){const r=reviewOf(id);return r?(r.decision==='accepted'?'已采纳':'已驳回'):'待复核'}
function doReview(id:string,decision:ReviewDecision){submitReview(id,decision);reviews.value=getReviews()}
function submit(){try{const record=analyse(student.value,answer.value);saveEvidence(record);records.value=getEvidence();latest.value=record;error.value=''}catch(e){error.value=(e as Error).message}}
function select(next:StudentId){student.value=next;answer.value='';latest.value=null;error.value=''}
function reset(){clearEvidence();records.value=[];latest.value=null;reviews.value=getReviews()}
</script>
<template><WorkspaceShell project="MindTrace-Agent" eyebrow="LEARNING AGENT LAB" subtitle="让每一次学习反馈都有可追溯的依据" mode="规则基线 · 本地会话" :steps="['阅读任务','提交解释','查看个性化建议','教师审阅证据']"><div class="stage-intro"><div><span class="section-label">EVIDENCE-BASED LEARNING / DEMO</span><h2>过拟合诊断实验室</h2><p class="muted">规则模式，无外部大模型。反馈仅针对当前输入，不代表真实课堂成绩。</p></div><span class="pill">LOCAL SESSION</span></div><div class="case-switch"><span>任务案例</span><button v-for="c in CASES" :key="c.id" @click="chooseCase(c.id)" :aria-pressed="caseId===c.id">{{c.id.slice(-3)}} · {{c.focus}}</button><small>{{activeCase.origin==='teacher_baseline'?'教师基线案例':'本人新增案例'}}</small></div><div class="role-switch"><button @click="role='student'" :aria-pressed="role==='student'">学生工作区</button><button @click="role='teacher'" :aria-pressed="role==='teacher'">教师证据视图</button></div><template v-if="role==='student'"><div class="student-select"><span>演示身份</span><button @click="select('A')" :aria-pressed="student==='A'">学生 A</button><button @click="select('B')" :aria-pressed="student==='B'">学生 B</button><small>DEMO / SAMPLE 身份</small></div><section class="problem-card"><span class="section-label">{{activeCase.eyebrow}}</span><h2>{{activeCase.title}}</h2><p>{{activeCase.prompt}}</p><div class="metrics"><div v-for="m in activeCase.metrics" :key="m.label"><small>{{m.label}}</small><strong>{{m.value}}</strong></div></div><p class="muted case-origin">案例来源：{{activeCase.origin==='teacher_baseline'?'教师基线（CASE-001）':'本人新增案例'}} · 诊断重点：{{activeCase.focus}}</p></section><div class="learning-grid"><section class="panel"><span class="section-label">YOUR EXPLANATION</span><h3>写下你的判断</h3><textarea v-model="answer" rows="7" :aria-label="`学生 ${student} 的回答`" placeholder="例如：这可能是过拟合，因为训练集表现远高于验证集。我会尝试正则化并比较验证结果。"></textarea><div class="row"><button class="action" @click="submit">提交并获得规则反馈</button><span v-if="error" class="error">{{error}}</span></div></section><section class="panel feedback"><span class="section-label">TRACEABLE FEEDBACK</span><h3>{{latest?'给学生 '+latest.student+' 的建议':'等待回答'}}</h3><p v-if="latest">{{latest.feedback}}</p><p v-else class="muted">提交回答后，这里显示基于关键词与证据线索的规则建议。</p><div v-if="latest" class="trace"><span>{{latest.diagnosis}} · 错因：{{latest.error_type}} · 规则置信度 {{latest.confidence}}</span><small>来源：当前本地会话 · {{latest.review_status}} · 需教师复核</small></div><div v-if="latest" class="evidence-box"><span class="section-label">EVIDENCE CHAIN / NOT_VERIFIED</span><h4>诊断依据（{{latest.evidence_chain.length}} 条）</h4><p class="muted">{{latest.notice}}</p><ul><li v-for="(item,i) in latest.evidence_chain" :key="i"><b>{{item.claim}}</b><small>{{item.source}} · {{item.ref}} · {{item.verified ? 'verified' : 'not_verified'}}</small><span>{{item.value}}</span></li></ul></div></section></div><section class="panel recent"><span class="section-label">LEARNING EVIDENCE</span><h3>学生 {{student}} 的当前会话记录</h3><p v-if="!selected.length" class="muted">暂无记录；提交后将保存在本机浏览器。</p><article v-for="record in selected.slice(0,3)" :key="record.id"><time>{{new Date(record.createdAt).toLocaleString('zh-CN')}}</time><p>{{record.answer}}</p><small>{{record.diagnosis}}</small></article></section></template><template v-else><div class="teacher-head"><div><span class="section-label">TEACHER REVIEW / CURRENT BROWSER</span><h2>学习证据记录</h2><p class="muted">仅显示本机当前浏览器录入的演示回答，不含真实学生资料。</p></div><button class="secondary" @click="reset">清空本地演示记录</button></div><div class="review-stats"><span>记录 {{stats.total_records}}</span><span>待复核 {{stats.pending}}</span><span>已采纳 {{stats.accepted}}</span><span>已驳回 {{stats.rejected}}</span><span>平均证据 {{stats.avg_evidence_items}} 条</span></div><div class="teacher-grid"><section v-for="id in (['A','B'] as StudentId[])" :key="id" class="panel"><span class="section-label">DEMO STUDENT {{id}}</span><h3>{{records.filter(x=>x.student===id).length}} 条回答</h3><p v-if="!records.some(x=>x.student===id)" class="muted">当前会话暂无记录</p><article v-for="record in records.filter(x=>x.student===id)" :key="record.id" class="evidence-item"><small>{{new Date(record.createdAt).toLocaleString('zh-CN')}} · {{record.mode}}</small><p><b>回答：</b>{{record.answer}}</p><p><b>规则反馈：</b>{{record.feedback}}</p><span class="pill">{{record.source}} · {{record.error_type}} · 证据 {{record.evidence_chain.length}} 条</span><div class="review-actions"><small>{{reviewLabel(record.id)}}</small><button class="secondary" @click="doReview(record.id,'accepted')">采纳</button><button class="secondary" @click="doReview(record.id,'rejected')">驳回</button></div></article></section></div></template><template #drawer="{active}"><p>{{['查看训练与验证表现，提出初步解释。','写下个人回答，记录输入原文。','规则基线按概念、证据与行动给出不同建议。','教师读取本机记录，自行审查；系统不自动评级。'][active]}}</p><p class="muted">数据：localStorage · 可随时清除</p></template></WorkspaceShell></template>
<style scoped>.stage-intro,.teacher-head{display:flex;justify-content:space-between;align-items:center;gap:15px;margin-bottom:18px}.stage-intro h2,.teacher-head h2{margin:6px 0;font-size:25px}.stage-intro p,.teacher-head p{margin:0}.role-switch{display:flex;gap:7px;border-bottom:1px solid #315a42;padding-bottom:12px;margin-bottom:15px}.role-switch button,.student-select button{background:#173a2a;color:#c3e1cc;border:1px solid #3b684b;border-radius:9px;padding:9px 13px}.role-switch button[aria-pressed=true],.student-select button[aria-pressed=true]{background:#4ba676;color:#092018;border-color:#9fe6b2}.student-select{display:flex;gap:8px;align-items:center;margin-bottom:14px;flex-wrap:wrap}.student-select span{color:#afd5ba}.student-select small{color:#8fbaa1}.problem-card{padding:25px;border:1px solid #5b8566;border-radius:16px;background:linear-gradient(105deg,#153c29,#10281f);margin-bottom:15px}.problem-card h2{font-size:25px;margin:8px 0}.problem-card p{font-size:16px;color:#d5eedb}.metrics{display:flex;gap:9px;flex-wrap:wrap;margin-top:22px}.metrics div{display:grid;gap:4px;min-width:120px;border:1px solid #4d805d;border-radius:10px;padding:12px 16px;background:#0a2119}.metrics small{font-size:10px;color:#8cb89d}.metrics strong{font-size:26px;color:#b9f6c4}.learning-grid,.teacher-grid{display:grid;grid-template-columns:1fr 1fr;gap:14px}.learning-grid textarea{width:100%;resize:vertical;background:#091c15;color:#eef8ef;border:1px solid #4b795c;border-radius:9px;padding:12px;margin:0 0 12px}.feedback p{line-height:1.7}.trace{display:grid;gap:8px;border-top:1px solid #3a6047;margin-top:20px;padding-top:12px;color:#b2e4bd}.trace small,.evidence-item small{color:#89b99a}.error{color:#ffcfac}.recent{margin-top:14px}.recent article,.evidence-item{border-top:1px solid #315a42;padding:10px 0}.recent article p,.evidence-item p{margin:5px 0;color:#cce4d2}.recent time,.recent small{font-size:11px;color:#8db69b}@media(max-width:700px){.stage-intro,.teacher-head{flex-direction:column;align-items:start}.learning-grid,.teacher-grid{grid-template-columns:1fr}.problem-card{padding:16px}}.evidence-box{margin-top:14px;border-top:1px solid #3a6047;padding-top:12px}.evidence-box h4{margin:8px 0 4px;font-size:15px;color:#eaf7f1}.evidence-box ul{list-style:none;margin:10px 0 0;padding:0;display:grid;gap:8px}.evidence-box li{border:1px solid #315a42;border-radius:9px;padding:9px 11px;background:#0c261b;display:grid;gap:3px}.evidence-box li b{font-size:13px;color:#d5eedb}.evidence-box li small{font-size:10px;color:#8cb89d;word-break:break-all}.evidence-box li span{font-size:12px;color:#b9d3c2;word-break:break-all}.case-switch{display:flex;gap:8px;align-items:center;flex-wrap:wrap;margin-bottom:14px}.case-switch span{color:#afd5ba;font-size:12px}.case-switch button{background:#173a2a;color:#c3e1cc;border:1px solid #3b684b;border-radius:9px;padding:8px 11px;font-size:12px}.case-switch button[aria-pressed=true]{background:#4ba676;color:#092018;border-color:#9fe6b2}.case-switch small{color:#8fbaa1;font-size:11px}.case-origin{margin:14px 0 0;font-size:12px}.review-stats{display:flex;gap:9px;flex-wrap:wrap;margin-bottom:14px}.review-stats span{border:1px solid #4d8665;border-radius:20px;padding:6px 12px;font-size:12px;color:#bbebc6;background:#1a4230}.review-actions{display:flex;gap:7px;align-items:center;flex-wrap:wrap;margin-top:10px}.review-actions small{color:#a2c3ae;font-size:11px}.review-actions button{padding:6px 10px;font-size:12px}</style>

